  builder_.add_volume_ratio_at_entry(volume_ratio_at_entry);
  builder_.add_indicators_at_entry(indicators_at_entry);
  builder_.add_original_target3(original_target3);
  builder_.add_original_target2(original_target2);
  builder_.add_original_target1(original_target1);
  builder_.add_confidence(confidence);
  builder_.add_pattern_name(pattern_name);
  builder_.add_mfe_atr(mfe_atr);
  builder_.add_mae_atr(mae_atr);
  builder_.add_stop_distance_atr(stop_distance_atr);
  builder_.add_atr10_price(atr10_price);
  builder_.add_theoretical_rrr(theoretical_rrr);
  builder_.add_realized_rrr(realized_rrr);
  builder_.add_target_distance_ticks(target_distance_ticks);
